insert into recipes (household_id, title, time_minutes, servings, steps, notes, created_by) values ('11111111-1111-1111-1111-111111111111', 'גלידת חלבון שוקולד (נינג''ה קרימי)', 10, 2, '["מערבבים בקערה את משקה החלבון, היוגורט, הקקאו, הממתיק והקסנטן עד אחידות.", "יוצקים לפיינט של הקרימי עד קו ה-MAX ומקפיאים 24 שעות.", "מריצים על תוכנית Gelato. אם אבקתי - Respin עם שתי כפות משקה חלבון."]'::jsonb, 'קרימי Deluxe. מקפיאים 24 שעות, סופינג על Gelato. אם יוצא קרה מדי - Respin עם שתי כפות משקה חלבון.', 'יובל');
insert into recipe_ingredients (recipe_id, household_id, name, amount, unit, grams, nutrition_key, kcal, protein, matched, position) select id, '11111111-1111-1111-1111-111111111111', v.name, v.amount, v.unit, v.grams, v.nutrition_key, v.kcal, v.protein, v.matched, v.position from recipes, (values ('משקה חלבון שוקולד', 350, 'מ"ל', 350, 'protein_drink', 217.0, 19.95, true, 0),('יוגורט חלבון טבעי', 200, 'גרם', 200, 'protein_yogurt', 114.0, 20.0, true, 1),('קקאו', 10, 'גרם', 10, 'cocoa', 22.8, 1.96, true, 2),('ממתיק', 15, 'גרם', 15, 'sweetener', null, null, true, 3),('קסנטן', 0.5, 'כפית', 2.5, 'xanthan', 7.5, null, true, 4)) as v(name, amount, unit, grams, nutrition_key, kcal, protein, matched, position) where recipes.title = 'גלידת חלבון שוקולד (נינג''ה קרימי)' and recipes.household_id = '11111111-1111-1111-1111-111111111111';
insert into recipes (household_id, title, time_minutes, servings, steps, notes, created_by) values ('11111111-1111-1111-1111-111111111111', 'גלידת חלבון קרמל מלוח (ללא קוטג'')', 10, 2, '["מערבבים את כל המרכיבים עד אחידות.", "יוצקים לפיינט ומקפיאים 24 שעות.", "מריצים על Gelato, Respin במידת הצורך."]'::jsonb, 'גרסה בלי קוטג''. השמנת נותנת מרקם חלק.', 'יובל');
