insert into recipes (household_id, title, time_minutes, servings, steps, notes, created_by) values ('11111111-1111-1111-1111-111111111111', 'נודלס ווק עם פרגיות', 25, 4, '["מבשלים את האטריות לפי ההוראות, שוטפים ומסננים.", "מטגנים פרגיות בחתיכות באש גבוהה 4-5 דקות, מוציאים.", "מטגנים בצל, גזר, פלפל ופטריות 3-4 דקות. מוסיפים שום וג''ינג''ר לדקה.", "מחזירים את הפרגיות, מוסיפים אטריות ורוטב סויה, מערבבים דקה-שתיים ומגישים."]'::jsonb, 'אש גבוהה, לא לדחוס את הווק. אפשר להחליף ירקות לפי מה שיש.', 'יובל');
